questionvariables.text:
/* Altitudes: 21 observations */
n: 21;
t: makelist(i-11,i,1,n);

alt0: 1400+50*rand(5);
alt_step: 65+5*rand(4);
altitudes: makelist(alt0+alt_step*t[i],i,1,n);

/* Pearson correlation function */
corr(A,B):=block(
    [m:length(A),ma,mb,sa,sb,sab],
    ma:sum(A[k],k,1,m)/m,
    mb:sum(B[k],k,1,m)/m,
    sa:sum((A[k]-ma)^2,k,1,m),
    sb:sum((B[k]-mb)^2,k,1,m),
    sab:sum((A[k]-ma)*(B[k]-mb),k,1,m),
    float(sab/sqrt(sa*sb))
);

/* Weak or strong negative correlation */
case: rand(2);

r_target:
    if case=0
    then -(25+rand(11))/100
    else -(84+rand(9))/100;

/* Random noise, centred and orthogonal to altitude */
raw: makelist(rand(201)-100,i,1,n);
rawmean: sum(raw[i],i,1,n)/n;
slope_noise:
    sum(t[i]*raw[i],i,1,n)/
    sum(t[i]^2,i,1,n);

u: makelist(
    raw[i]-rawmean-slope_noise*t[i],
    i,1,n
);

/* Scale noise to obtain the target correlation */
slope_temp: -0.4;
scale:
    abs(slope_temp)*
    sqrt(
        (1/r_target^2-1)*
        sum(t[i]^2,i,1,n)/
        sum(u[i]^2,i,1,n)
    );

/* Temperatures rounded to one decimal place */
temps: makelist(
    float(round(10*(18+slope_temp*t[i]+scale*u[i]))/10),
    i,1,n
);

/* Downward-opening quadratic tea yield */
tea_slope: rand(41)-20;
tea_noise: makelist(rand(141)-70,i,1,n);

yields: makelist(
    round(2800-12*t[i]^2+tea_slope*t[i]+tea_noise[i]),
    i,1,n
);

/* Downloadable data */
lab: [
    "Altitude (m)",
    "Mean annual temperature (deg C)",
    "Annual tea yield (kg/ha)"
];

data: makelist(
    [altitudes[i],temps[i],yields[i]],
    i,1,n
);

/* Correlations calculated from the actual CSV values */
rxy: corr(altitudes,temps);
rxz: corr(altitudes,yields);

rxy_display: float(round(1000*rxy)/1000);
rxz_display: float(round(1000*rxz)/1000);

/* Correct classifications */
ta_xy: if case=0 then 2 else 4;
ta_xz: 5;

/* Dropdown options */

/* Correct classification */
ta_xy: if case=0 then 2 else 4;

/* Dropdown options */
options_xy: [
    [0,false,"No relationship"],
    [1,false,"Weak positive linear relationship"],
    [2,if case=0 then true else false,
       "Weak negative linear relationship"],
    [3,false,"Strong positive linear relationship"],
    [4,if case=1 then true else false,
       "Strong negative linear relationship"],
    [5,false,"None of the above"]
];

options_xz: [
    [0,false,"No relationship"],
    [1,false,"Weak positive linear relationship"],
    [2,false,"Weak negative linear relationship"],
    [3,false,"Strong positive linear relationship"],
    [4,false,"Strong negative linear relationship"],
    [5,true,"None of the above"]
];

feedbackvariables.text:
/* Classify the student's own correlation coefficient. */

ecf_r: float(ans1);

ecf_ta:
    if ecf_r < -1 or ecf_r > 1 then -1
    elseif ecf_r <= -0.6 then 4
    elseif ecf_r <= -0.1 then 2
    elseif ecf_r >= 0.6 then 3
    elseif ecf_r >= 0.1 then 1
    else -1;
